CREATE TABLE IF NOT EXISTS p11_friend_duels (id VARCHAR(64) PRIMARY KEY,viewer_id BIGINT NOT NULL,opponent_id BIGINT NOT NULL,attacker LONGBLOB NOT NULL,defender LONGBLOB NOT NULL,snapshot_hash VARCHAR(64) NOT NULL,configuration_hash VARCHAR(64) NOT NULL,capability_hash VARCHAR(64) NOT NULL,seed BIGINT NOT NULL,created_at BIGINT NOT NULL,expires_at BIGINT NOT NULL,KEY idx_p11_duel_owner(viewer_id),KEY idx_p11_duel_opponent(opponent_id),KEY idx_p11_duel_expiry(expires_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
